// 953261 Lab 2 — automatic checks. Run:  npm test
// Read the first failing test: it tells you which task to fix and what was expected.
// Do not edit this file.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { menu } from "../data/menu.js";
import { orders } from "../data/orders.js";
import * as cafe from "../src/cafe.js";

const menuBefore = structuredClone(menu);

test("Task 1  menuNames returns every name in order", () => {
  const names = cafe.menuNames(menu);
  assert.equal(names?.length, 9);
  assert.equal(names[0], "Thai Iced Tea");
  assert.equal(names[8], "Coconut Ice Cream");
});

test("Task 2  availableItems keeps only available items", () => {
  const items = cafe.availableItems(menu);
  assert.equal(items?.length, 7);
  assert.ok(items.every((i) => i.available === true));
});

test("Task 3  findItem finds by id, undefined when missing", () => {
  assert.equal(cafe.findItem(menu, "F01")?.name, "Khao Soi");
  assert.equal(cafe.findItem(menu, "X99"), undefined);
});

test("Task 4  availableIn returns names of available items in a category", () => {
  assert.deepEqual(cafe.availableIn(menu, "dessert"), ["Mango Sticky Rice", "Coconut Ice Cream"]);
  assert.deepEqual(cafe.availableIn(menu, "food"), ["Khao Soi", "Basil Chicken Rice"]);
  assert.deepEqual(cafe.availableIn(menu, "pizza"), []);
});

test("Task 5  menuLine formats one line for the menu board", () => {
  assert.equal(cafe.menuLine(menu[0]), "Thai Iced Tea — 45 THB");
  assert.equal(cafe.menuLine(menu[3]), "Butterfly Pea Soda — 50 THB (sold out)");
});

test("Task 6  withDiscount returns a new item and leaves the original alone", () => {
  const original = menu[0];
  const cheaper = cafe.withDiscount(original, 10);
  assert.equal(cheaper?.price, 41);
  assert.equal(cheaper.name, "Thai Iced Tea");
  assert.equal(original.price, 45, "the original item was changed — use spread { ...item }");
  assert.notEqual(cheaper, original, "return a NEW object, not the same one");
});

test("Task 7  orderTotal adds price × qty for every line", () => {
  assert.equal(cafe.orderTotal(orders[0], menu), 160);
  assert.equal(cafe.orderTotal(orders[2], menu), 250);
  assert.equal(cafe.orderTotal({ id: "E", customer: "x", items: [] }, menu), 0);
});

test("Task 8  averageOrder averages all order totals", () => {
  assert.equal(cafe.averageOrder(orders, menu), 165.83);
  assert.equal(cafe.averageOrder([], menu), 0);
});

test("Rules  src/cafe.js uses array methods, not for/while loops", () => {
  const code = readFileSync(new URL("../src/cafe.js", import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\/\/.*$/gm, "");
  assert.doesNotMatch(code, /\b(for|while)\s*\(/, "found a for/while loop — use map, filter, find or reduce");
});

test("Rules  the menu data was not changed (no mutation)", () => {
  assert.deepEqual(menu, menuBefore, "a function changed the menu array — return new arrays/objects instead");
});

// ───────────── Stretch ─────────────
// Shown as "todo" (not failed) until you start them.
const notStarted = (fn) => { try { return fn() === undefined; } catch { return false; } };
test("Stretch 9   bestSeller returns the most-ordered item name", { todo: notStarted(() => cafe.bestSeller(orders, menu)) }, () => {
  assert.equal(cafe.bestSeller(orders, menu), "Thai Iced Tea");
});

test("Stretch 10  namesByCategory groups names by category", { todo: notStarted(() => cafe.namesByCategory(menu)) }, () => {
  const groups = cafe.namesByCategory(menu);
  assert.deepEqual(Object.keys(groups).sort(), ["dessert", "drink", "food"]);
  assert.deepEqual(groups.dessert, ["Mango Sticky Rice", "Coconut Ice Cream"]);
  assert.equal(groups.drink.length, 4);
});
